use xiom.io;

type Character = {
  name: Str;
  hp: Int;
  max_hp: Int;
}

fn Character.take_damage(self, amount: Int) {
  hp = hp - amount;
  if hp < 0 {
    hp = 0;
  }
}

fn Character.heal(self, amount: Int) {
  hp = hp + amount;
  if hp > max_hp {
    hp = max_hp;
  }
}

fn main() -> Int {
  var hero = Character{ name: "Mage"; hp: 50; max_hp: 100; };
  hero.take_damage(70);
  hero.heal(40);
  return hero.hp;
}
